package host

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// agentTemplates are the adapter files the go-grpc agent renders
// (codefly-dev/service-go-grpc templates/factory/code/pkg/adapters/*_gen.go.tmpl).
var agentTemplates = map[string]bool{
	"connect_gen.go": true,
	"cors_gen.go":    true,
	"grpc_gen.go":    true,
	"rest_gen.go":    true,
	"server_gen.go":  true,
}

// agentMarker is the go-grpc agent's generated-code marker. The agent writes it
// instead of the "// Code generated … DO NOT EDIT." line ast.IsGenerated
// recognises, and its own Sync decides which files it owns by it.
const agentMarker = "This code is generated by the agent. Do not edit this file!"

const grpcImport = "google.golang.org/grpc"

var fromEndpoint = regexp.MustCompile(`^Register\w+HandlerFromEndpoint$`)

// isAgentAdapter reports whether file is one of the agent's generated adapters:
// it has one of the agent's template names under a pkg/adapters directory, and
// it carries a generated-code marker (the agent's own, or the standard one)
// before its first declaration. A hand-written *_gen.go is not one.
func isAgentAdapter(file *ast.File, relative string) bool {
	directory, base := path.Split(relative)
	if !agentTemplates[base] || !strings.HasSuffix(strings.TrimSuffix(directory, "/"), "/pkg/adapters") {
		return false
	}
	if ast.IsGenerated(file) {
		return true
	}
	header := file.End()
	if len(file.Decls) > 0 {
		header = file.Decls[0].Pos()
	}
	for _, group := range file.Comments {
		if group.Pos() < header && strings.Contains(group.Text(), agentMarker) {
			return true
		}
	}
	return false
}

// checkSelfDials judges every gRPC dial in the agent's generated adapters of
// one package, type-checked so an identifier is the object it resolves to, not
// its spelling:
//   - each grpc.NewClient, grpc.Dial, grpc.DialContext and
//     Register…HandlerFromEndpoint passes, as its options, a call of the
//     package's gatewayDialOptions, or a local variable whose one and only
//     write is its definition from such a call and whose only uses are dial
//     options arguments (no aliases, indexing, slicing, calls or escapes);
//   - gatewayDialOptions, declared in a generated adapter, builds its options
//     from a slice literal holding grpc.WithNoProxy() and returns them with
//     grpc.WithTransportCredentials(loopbackTransport{…}) appended last, in
//     straight-line code (no option is set in a branch, a loop or a closure);
//   - loopbackTransport and its ClientHandshake are declared in a generated
//     adapter.
func checkSelfDials(t *testing.T, root, directory string) []string {
	files := token.NewFileSet()
	var parsed []*ast.File
	generated := map[*ast.File]bool{}
	entries, err := os.ReadDir(directory)
	if err != nil {
		t.Fatal(err)
	}
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		full := filepath.Join(directory, name)
		file, err := parser.ParseFile(files, full, nil, parser.ParseComments)
		if err != nil {
			t.Fatalf("%s: %v", full, err)
		}
		relative, _ := filepath.Rel(root, full)
		generated[file] = isAgentAdapter(file, filepath.ToSlash(relative))
		parsed = append(parsed, file)
	}
	c := selfDials{root: root, files: files, generated: generated, info: &types.Info{
		Defs: map[*ast.Ident]types.Object{},
		Uses: map[*ast.Ident]types.Object{},
	}}
	// Imports resolve to empty packages: the check needs the identity of this
	// package's own objects and of the grpc package name, not the imported API,
	// so the type errors that follow are expected and ignored.
	config := types.Config{Importer: emptyPackages{}, Error: func(error) {}}
	c.pkg, _ = config.Check(directory, files, parsed, c.info)
	c.parsed = parsed
	return c.violations()
}

type selfDials struct {
	root      string
	files     *token.FileSet
	parsed    []*ast.File
	generated map[*ast.File]bool
	info      *types.Info
	pkg       *types.Package
}

func (c selfDials) where(node ast.Node) string {
	position := c.files.Position(node.Pos())
	relative, _ := filepath.Rel(c.root, position.Filename)
	return fmt.Sprintf("%s:%d", filepath.ToSlash(relative), position.Line)
}

// declaredInAdapter reports whether object is declared in a generated adapter.
func (c selfDials) declaredInAdapter(object types.Object) bool {
	for file, generated := range c.generated {
		if generated && file.FileStart <= object.Pos() && object.Pos() < file.FileEnd {
			return true
		}
	}
	return false
}

func (c selfDials) violations() []string {
	var dials []ast.Node
	var violations []string
	seam, _ := c.pkg.Scope().Lookup("gatewayDialOptions").(*types.Func)
	for _, file := range c.parsed {
		if !c.generated[file] {
			continue
		}
		ast.Inspect(file, func(node ast.Node) bool {
			call, ok := node.(*ast.CallExpr)
			if !ok {
				return true
			}
			options, ok := c.dialOptions(call)
			if !ok {
				return true
			}
			dials = append(dials, call)
			if seam == nil || !c.fromSeam(options, seam) {
				violations = append(violations, fmt.Sprintf("%s: a generated self-dial must pass gatewayDialOptions(…), or a local defined once from it and used only as dial options (no aliases, indexing, slicing, other calls or address-taking), as its options", c.where(call)))
			}
			return true
		})
	}
	if len(dials) == 0 {
		return violations
	}
	if reason := c.seamRefusal(seam); reason != "" {
		violations = append(violations, fmt.Sprintf("%s: gatewayDialOptions %s; regenerate with go-grpc 0.1.67 or later", c.where(dials[0]), reason))
	}
	sort.Strings(violations)
	return violations
}

// dialOptions returns the options argument of a gRPC dial: the spread final
// argument of grpc.NewClient, Dial or DialContext, or the last argument of a
// Register…HandlerFromEndpoint.
func (c selfDials) dialOptions(call *ast.CallExpr) (ast.Expr, bool) {
	selector, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, false
	}
	if c.isGRPC(selector, "NewClient", "Dial", "DialContext") {
		count := 2
		if selector.Sel.Name == "DialContext" {
			count = 3
		}
		if len(call.Args) != count || !call.Ellipsis.IsValid() {
			return nil, true // anything but one spread options argument is refused
		}
		return call.Args[count-1], true
	}
	if fromEndpoint.MatchString(selector.Sel.Name) {
		if len(call.Args) == 0 || call.Ellipsis.IsValid() {
			return nil, true
		}
		return call.Args[len(call.Args)-1], true
	}
	return nil, false
}

// isGRPC reports whether selector names one of the given members of the grpc
// package, by the package the qualifier resolves to.
func (c selfDials) isGRPC(selector *ast.SelectorExpr, members ...string) bool {
	qualifier, ok := selector.X.(*ast.Ident)
	if !ok {
		return false
	}
	name, ok := c.info.Uses[qualifier].(*types.PkgName)
	if !ok || name.Imported().Path() != grpcImport {
		return false
	}
	for _, member := range members {
		if selector.Sel.Name == member {
			return true
		}
	}
	return false
}

// callsFunc reports whether expression is a call of function, by identity.
func (c selfDials) callsFunc(expression ast.Expr, function types.Object) bool {
	call, ok := expression.(*ast.CallExpr)
	if !ok {
		return false
	}
	identifier, ok := call.Fun.(*ast.Ident)
	return ok && c.info.Uses[identifier] == function
}

// fromSeam reports whether options is a call of seam, or a local variable whose
// one and only write is its definition from a call of seam, and whose every
// use is the entire options argument of a dial. Checking uses by object identity
// closes backing-array escapes without trying to infer what arbitrary calls do.
func (c selfDials) fromSeam(options ast.Expr, seam *types.Func) bool {
	if options == nil {
		return false
	}
	if c.callsFunc(options, seam) {
		return true
	}
	identifier, ok := options.(*ast.Ident)
	if !ok {
		return false
	}
	variable, ok := c.info.Uses[identifier].(*types.Var)
	if !ok || variable.Parent() == c.pkg.Scope() {
		return false
	}
	allowed := map[*ast.Ident]bool{}
	for _, file := range c.parsed {
		ast.Inspect(file, func(node ast.Node) bool {
			if call, ok := node.(*ast.CallExpr); ok {
				if argument, dial := c.dialOptions(call); dial {
					if id, ok := argument.(*ast.Ident); ok {
						allowed[id] = true
					}
				}
			}
			return true
		})
	}
	if !c.onlyUses(variable, allowed) {
		return false
	}
	writes := c.writes(variable)
	if len(writes) != 1 {
		return false
	}
	definition, ok := writes[0].(*ast.AssignStmt)
	if !ok || definition.Tok != token.DEFINE || len(definition.Lhs) != len(definition.Rhs) {
		return false
	}
	for i, target := range definition.Lhs {
		if id, ok := target.(*ast.Ident); ok && c.info.Defs[id] == variable {
			return c.callsFunc(definition.Rhs[i], seam)
		}
	}
	return false
}

// onlyUses refuses any occurrence outside the explicitly permitted positions,
// including reads that can alias a slice or expose its backing array to a call.
func (c selfDials) onlyUses(variable *types.Var, allowed map[*ast.Ident]bool) bool {
	for identifier, object := range c.info.Uses {
		if object == variable && !allowed[identifier] {
			return false
		}
	}
	return true
}

// writes are the statements and expressions that can change variable: an
// assignment to it or to an element of it, an increment, a range over into
// it, and taking its address.
func (c selfDials) writes(variable *types.Var) []ast.Node {
	refers := func(expression ast.Expr) bool {
		for {
			switch e := expression.(type) {
			case *ast.Ident:
				return c.info.Defs[e] == variable || c.info.Uses[e] == variable
			case *ast.IndexExpr:
				expression = e.X
			case *ast.SliceExpr:
				expression = e.X
			case *ast.ParenExpr:
				expression = e.X
			case *ast.StarExpr:
				expression = e.X
			default:
				return false
			}
		}
	}
	var writes []ast.Node
	for _, file := range c.parsed {
		ast.Inspect(file, func(node ast.Node) bool {
			switch n := node.(type) {
			case *ast.AssignStmt:
				for _, target := range n.Lhs {
					if refers(target) {
						writes = append(writes, n)
						break
					}
				}
			case *ast.IncDecStmt:
				if refers(n.X) {
					writes = append(writes, n)
				}
			case *ast.RangeStmt:
				if (n.Key != nil && refers(n.Key)) || (n.Value != nil && refers(n.Value)) {
					writes = append(writes, n)
				}
			case *ast.UnaryExpr:
				if n.Op == token.AND && refers(n.X) {
					writes = append(writes, n)
				}
			case *ast.ValueSpec:
				for _, name := range n.Names {
					if c.info.Defs[name] == variable {
						writes = append(writes, n)
					}
				}
			}
			return true
		})
	}
	return writes
}

// seamRefusal says what is wrong with the package's gatewayDialOptions, or ""
// when it refuses the environment proxy and ends on the loopback transport.
func (c selfDials) seamRefusal(seam *types.Func) string {
	if seam == nil {
		return "is not declared in this package"
	}
	if !c.declaredInAdapter(seam) {
		return "is not declared in a generated adapter"
	}
	declaration := c.funcDecl(seam)
	if declaration == nil || declaration.Body == nil || len(declaration.Body.List) == 0 {
		return "has no body"
	}
	// Reject these operations anywhere in the body, including nested expressions
	// or closures; neither copy nor indexed writes can preserve the proof.
	mutation := false
	ast.Inspect(declaration.Body, func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.AssignStmt:
			for _, target := range n.Lhs {
				if _, ok := target.(*ast.Ident); !ok {
					mutation = true
				}
			}
		case *ast.CallExpr:
			if c.isBuiltin(n.Fun, "copy") {
				mutation = true
			}
		}
		return true
	})
	if mutation {
		return "contains an indexed, sliced or indirect assignment, or copy"
	}
	statements := declaration.Body.List
	final, ok := statements[len(statements)-1].(*ast.ReturnStmt)
	if !ok || len(final.Results) != 1 {
		return "does not end by returning its options"
	}
	built, ok := final.Results[0].(*ast.CallExpr)
	if !ok || !c.isBuiltin(built.Fun, "append") || built.Ellipsis.IsValid() || len(built.Args) != 2 {
		return "does not return append(options, grpc.WithTransportCredentials(loopbackTransport{…}))"
	}
	if reason := c.loopbackRefusal(built.Args[1]); reason != "" {
		return reason
	}
	identifier, ok := built.Args[0].(*ast.Ident)
	options, _ := c.info.Uses[identifier].(*types.Var)
	if !ok || options == nil || options.Parent() == c.pkg.Scope() {
		return "does not return a local options slice"
	}
	noProxy := false
	allowed := map[*ast.Ident]bool{identifier: true}
	for _, statement := range statements[:len(statements)-1] {
		assignment, ok := statement.(*ast.AssignStmt)
		if !ok {
			return "sets its options outside straight-line assignments"
		}
		if len(assignment.Lhs) != 1 || len(assignment.Rhs) != 1 {
			return "must define or append its options in single-value assignments"
		}
		id, ok := assignment.Lhs[0].(*ast.Ident)
		if !ok || (c.info.Defs[id] != options && c.info.Uses[id] != options) {
			return "assigns something other than its options slice"
		}
		allowed[id] = true
		value := assignment.Rhs[0]
		switch {
		case assignment.Tok == token.DEFINE && c.info.Defs[id] == options:
			noProxy = c.holdsNoProxy(value)
		case assignment.Tok == token.ASSIGN:
			grown, ok := value.(*ast.CallExpr)
			var first *ast.Ident
			if ok && len(grown.Args) > 0 {
				first, _ = grown.Args[0].(*ast.Ident)
			}
			if !ok || !c.isBuiltin(grown.Fun, "append") || first == nil || c.info.Uses[first] != options {
				return "replaces its options rather than appending to them"
			}
			allowed[first] = true
		default:
			return "writes its options other than by definition or append"
		}
	}
	if !c.onlyUses(options, allowed) {
		return "uses its options outside the permitted append and return positions"
	}
	if !noProxy {
		return "does not define its options from a slice literal holding grpc.WithNoProxy()"
	}
	return ""
}

func (c selfDials) funcDecl(function *types.Func) *ast.FuncDecl {
	for _, file := range c.parsed {
		for _, declaration := range file.Decls {
			if fn, ok := declaration.(*ast.FuncDecl); ok && c.info.Defs[fn.Name] == function {
				return fn
			}
		}
	}
	return nil
}

func (c selfDials) isBuiltin(expression ast.Expr, name string) bool {
	identifier, ok := expression.(*ast.Ident)
	if !ok {
		return false
	}
	builtin, ok := c.info.Uses[identifier].(*types.Builtin)
	return ok && builtin.Name() == name
}

// holdsNoProxy reports whether value is a slice literal with grpc.WithNoProxy()
// among its elements.
func (c selfDials) holdsNoProxy(value ast.Expr) bool {
	literal, ok := value.(*ast.CompositeLit)
	if !ok {
		return false
	}
	for _, element := range literal.Elts {
		call, ok := element.(*ast.CallExpr)
		if !ok || len(call.Args) != 0 {
			continue
		}
		if selector, ok := call.Fun.(*ast.SelectorExpr); ok && c.isGRPC(selector, "WithNoProxy") {
			return true
		}
	}
	return false
}

// loopbackRefusal says what is wrong with the option appended last, or "" when
// it is grpc.WithTransportCredentials(loopbackTransport{…}) and that type and
// its ClientHandshake are the generated ones.
func (c selfDials) loopbackRefusal(option ast.Expr) string {
	const want = "does not append grpc.WithTransportCredentials(loopbackTransport{…}) last"
	call, ok := option.(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return want
	}
	selector, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || !c.isGRPC(selector, "WithTransportCredentials") {
		return want
	}
	literal, ok := call.Args[0].(*ast.CompositeLit)
	if !ok {
		return want
	}
	typeName, ok := literal.Type.(*ast.Ident)
	if !ok {
		return want
	}
	transport, ok := c.info.Uses[typeName].(*types.TypeName)
	if !ok || transport.Name() != "loopbackTransport" || transport.Parent() != c.pkg.Scope() || !c.declaredInAdapter(transport) {
		return "appends credentials last that are not the generated loopbackTransport"
	}
	named, ok := transport.Type().(*types.Named)
	if !ok {
		return "appends credentials last that are not the generated loopbackTransport"
	}
	for i := 0; i < named.NumMethods(); i++ {
		if method := named.Method(i); method.Name() == "ClientHandshake" && c.declaredInAdapter(method) {
			return ""
		}
	}
	return "appends a loopbackTransport whose ClientHandshake is not generated"
}

// emptyPackages imports every path as an empty, complete package named by its
// last path element (grpc for google.golang.org/grpc).
type emptyPackages struct{}

func (emptyPackages) Import(importPath string) (*types.Package, error) {
	name := importPath[strings.LastIndex(importPath, "/")+1:]
	if importPath == grpcImport {
		name = "grpc"
	}
	pkg := types.NewPackage(importPath, name)
	pkg.MarkComplete()
	return pkg, nil
}

const fixtureMarker = "/* -----\n\n⚠️ " + agentMarker + "\n\n----- */\n"

const fixtureSeam = `package adapters

` + fixtureMarker + `
import (
	"context"
	"net"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials"
	"google.golang.org/grpc/credentials/insecure"
)

func gatewayDialOptions(extra ...grpc.DialOption) []grpc.DialOption {
	options := []grpc.DialOption{grpc.WithNoProxy()}
	options = append(options, extra...)
	return append(options, grpc.WithTransportCredentials(loopbackTransport{insecure.NewCredentials()}))
}

type loopbackTransport struct{ credentials.TransportCredentials }

func (t loopbackTransport) ClientHandshake(ctx context.Context, authority string, conn net.Conn) (net.Conn, credentials.AuthInfo, error) {
	return t.TransportCredentials.ClientHandshake(ctx, authority, conn)
}
`

const fixtureDials = `package adapters

` + fixtureMarker + `
import (
	"context"

	"google.golang.org/grpc"
	gen "svc/pkg/gen"
)

func rest(ctx context.Context, extra []grpc.DialOption) {
	opts := gatewayDialOptions(extra...)
	_ = gen.RegisterSvcServiceHandlerFromEndpoint(ctx, nil, "127.0.0.1:1", opts)
	_, _ = grpc.NewClient("127.0.0.1:1", opts...)
	_, _ = grpc.NewClient("127.0.0.1:1", gatewayDialOptions(extra...)...)
}
`

// judge runs the gate over one adapter package written from sources.
func judge(t *testing.T, sources map[string]string) []string {
	t.Helper()
	root := t.TempDir()
	directory := filepath.Join(root, "svc", "pkg", "adapters")
	if err := os.MkdirAll(directory, 0o755); err != nil {
		t.Fatal(err)
	}
	var violations []string
	agentAdapters := false
	for name, source := range sources {
		path := filepath.Join(directory, name)
		if err := os.WriteFile(path, []byte(source), 0o600); err != nil {
			t.Fatal(err)
		}
		found, agentAdapter := inspect(t, path, "svc/pkg/adapters/"+name)
		violations = append(violations, found...)
		agentAdapters = agentAdapters || agentAdapter
	}
	if agentAdapters {
		violations = append(violations, checkSelfDials(t, root, directory)...)
	}
	return violations
}

// The generated self-dial rule, against the template's shape and the
// regressions r157 found: options followed by name, files exempt by name,
// a WithNoProxy in dead code, and credentials that are not loopback or not last.
func TestTheGeneratedSelfDialRule(t *testing.T) {
	replace := func(source, old, new string) string {
		if !strings.Contains(source, old) {
			t.Fatalf("fixture does not contain %q", old)
		}
		return strings.Replace(source, old, new, 1)
	}
	for _, c := range []struct {
		name    string
		sources map[string]string
		refusal string // "" when the package is allowed
	}{
		{"the template's shape", map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": fixtureDials}, ""},
		{"a same-named variable in another function",
			map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": fixtureDials + `
func other(raw []grpc.DialOption) {
	opts := raw
	_, _ = grpc.NewClient("remote.example:443", opts...)
}
`}, "a generated self-dial must pass gatewayDialOptions"},
		{"the options variable written again",
			map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": replace(fixtureDials,
				"opts := gatewayDialOptions(extra...)\n", "opts := gatewayDialOptions(extra...)\n\topts = extra\n")},
			"a generated self-dial must pass gatewayDialOptions"},
		{"a FromEndpoint dial with other options",
			map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": replace(fixtureDials, `"127.0.0.1:1", opts)`, `"remote.example:443", extra)`)},
			"a generated self-dial must pass gatewayDialOptions"},
		{"a hand-written file named like a template, without the marker",
			map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": replace(fixtureDials, fixtureMarker, "")},
			"grpc.NewClient must dial with host.DialOptions"},
		{"a marked file that is not one of the agent's templates",
			map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": fixtureDials, "mine_gen.go": replace(fixtureDials, "func rest(", "func mine(")},
			"grpc.NewClient must dial with host.DialOptions"},
		{"WithNoProxy only in dead code",
			map[string]string{"rest_gen.go": fixtureDials, "grpc_gen.go": replace(fixtureSeam,
				"options := []grpc.DialOption{grpc.WithNoProxy()}\n",
				"options := []grpc.DialOption{}\n\tif false {\n\t\toptions = append(options, grpc.WithNoProxy())\n\t}\n")},
			"sets its options outside straight-line assignments"},
		{"WithNoProxy evaluated but not kept",
			map[string]string{"rest_gen.go": fixtureDials, "grpc_gen.go": replace(fixtureSeam,
				"options := []grpc.DialOption{grpc.WithNoProxy()}\n",
				"_ = grpc.WithNoProxy()\n\toptions := []grpc.DialOption{}\n")},
			"assigns something other than its options slice"},
		{"options replaced inside the seam",
			map[string]string{"rest_gen.go": fixtureDials, "grpc_gen.go": replace(fixtureSeam,
				"options = append(options, extra...)\n", "options = extra\n")},
			"replaces its options rather than appending to them"},
		{"plain insecure credentials last",
			map[string]string{"rest_gen.go": fixtureDials, "grpc_gen.go": replace(fixtureSeam,
				"grpc.WithTransportCredentials(loopbackTransport{insecure.NewCredentials()})", "grpc.WithTransportCredentials(insecure.NewCredentials())")},
			"does not append grpc.WithTransportCredentials(loopbackTransport{…}) last"},
		{"loopback credentials not last",
			map[string]string{"rest_gen.go": fixtureDials, "grpc_gen.go": replace(fixtureSeam,
				"options = append(options, extra...)\n\treturn append(options, grpc.WithTransportCredentials(loopbackTransport{insecure.NewCredentials()}))",
				"options = append(options, grpc.WithTransportCredentials(loopbackTransport{insecure.NewCredentials()}))\n\treturn append(options, extra...)")},
			"does not return append(options, grpc.WithTransportCredentials(loopbackTransport{…}))"},
		{"no gatewayDialOptions in the package",
			map[string]string{"rest_gen.go": fixtureDials}, "gatewayDialOptions is not declared in this package"},
	} {
		t.Run(c.name, func(t *testing.T) {
			violations := judge(t, c.sources)
			if c.refusal == "" {
				if len(violations) != 0 {
					t.Fatalf("refused: %q", violations)
				}
				return
			}
			for _, violation := range violations {
				if strings.Contains(violation, c.refusal) {
					return
				}
			}
			t.Fatalf("want a refusal containing %q, got %q", c.refusal, violations)
		})
	}
}

func TestIndependentReviewSliceMutation(t *testing.T) {
	for name, change := range map[string]string{
		"alias erases loopback credentials": "alias := opts\n\talias[len(alias)-1] = grpc.WithTransportCredentials(insecure.NewCredentials())",
		"copy erases loopback credentials":  "copy(opts[len(opts)-1:], []grpc.DialOption{grpc.WithTransportCredentials(insecure.NewCredentials())})",
	} {
		t.Run(name, func(t *testing.T) {
			dials := strings.Replace(fixtureDials, "\"context\"", "\"context\"\n\"google.golang.org/grpc/credentials/insecure\"", 1)
			dials = strings.Replace(dials, "opts := gatewayDialOptions(extra...)", "opts := gatewayDialOptions(extra...)\n\t"+change, 1)
			got := judge(t, map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": dials})
			if len(got) == 0 {
				t.Fatal("unsafe mutable slice accepted with zero violations")
			} else {
				t.Log(got)
			}
		})
	}
	t.Run("seam erases WithNoProxy by indexed assignment", func(t *testing.T) {
		seam := strings.Replace(fixtureSeam, "options = append(options, extra...)", "options[0] = grpc.WithTransportCredentials(insecure.NewCredentials())\n\toptions = append(options, extra...)", 1)
		got := judge(t, map[string]string{"grpc_gen.go": seam, "rest_gen.go": fixtureDials})
		if len(got) == 0 {
			t.Fatal("WithNoProxy overwritten in seam accepted with zero violations")
		} else {
			t.Log(got)
		}
	})
}

func TestSelfDialOptionsCannotEscape(t *testing.T) {
	for name, use := range map[string]string{
		"alias without a visible write": "alias := opts; _ = alias",
		"indexed read":                  "_ = opts[0]",
		"indexed write":                 "opts[0] = extra[0]",
		"slice":                         "_ = opts[:]",
		"full slice":                    "_ = opts[:len(opts):cap(opts)]",
		"copy destination":              "copy(opts, extra)",
		"copy source":                   "copy(extra, opts)",
		"mutating call":                 "mutate(opts)",
		"variadic call":                 "mutateVariadic(opts...)",
		"address":                       "_ = &opts",
		"element address":               "_ = &opts[0]",
		"closure alias":                 "f := func() { mutate(opts) }; f()",
		"return escape":                 "f := func() []grpc.DialOption { return opts }; _ = f",
		"channel escape":                "ch := make(chan []grpc.DialOption, 1); ch <- opts",
		"append alias":                  "alias := append(opts, extra...); _ = alias",
		"dial target is not options":    "_, _ = grpc.NewClient(opts, gatewayDialOptions()...)",
		"deferred mutation":             "defer mutate(opts)",
	} {
		t.Run(name, func(t *testing.T) {
			dials := strings.Replace(fixtureDials, "opts := gatewayDialOptions(extra...)",
				"opts := gatewayDialOptions(extra...)\n\t"+use, 1)
			dials += "\nfunc mutate(options []grpc.DialOption) { options[0] = nil }\nfunc mutateVariadic(options ...grpc.DialOption) { options[0] = nil }\n"
			violations := judge(t, map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": dials})
			if !strings.Contains(strings.Join(violations, "\n"), "used only as dial options") {
				t.Fatalf("want a refusal explaining restricted options use, got %q", violations)
			}
		})
	}
}

func TestGatewayDialOptionsRefusesBackingArrayMutation(t *testing.T) {
	for name, use := range map[string]string{
		"copy statement":                   "copy(options, extra)",
		"copy expression":                  "n := copy(options, extra); _ = n",
		"copy in closure":                  "f := func() { copy(options, extra) }; f()",
		"indexed assignment":               "options[0] = extra[0]",
		"parenthesized indexed assignment": "(options[0]) = extra[0]",
		"slice assignment":                 "options[:] = extra",
		"alias":                            "alias := options; alias[0] = extra[0]",
		"call mutating backing array":      "mutate(options)",
		"mutation in append argument":      "options = append(options, mutate(options)...)",
		"address in append argument":       "options = append(options, mutatePointer(&options)...)",
		"reslice in append":                "options = append(options[:0], extra...)",
	} {
		t.Run(name, func(t *testing.T) {
			seam := strings.Replace(fixtureSeam, "options = append(options, extra...)",
				use+"\n\toptions = append(options, extra...)", 1)
			seam += "\nfunc mutate(options []grpc.DialOption) []grpc.DialOption { options[0] = nil; return options }\nfunc mutatePointer(options *[]grpc.DialOption) []grpc.DialOption { *options = nil; return nil }\n"
			violations := judge(t, map[string]string{"grpc_gen.go": seam, "rest_gen.go": fixtureDials})
			if !strings.Contains(strings.Join(violations, "\n"), "gatewayDialOptions ") {
				t.Fatalf("want a reason for refusing the seam, got %q", violations)
			}
		})
	}
}

func TestSelfDialOptionsAcceptsEachDial(t *testing.T) {
	for _, dial := range []string{
		`grpc.NewClient("127.0.0.1:1", OPTIONS...)`,
		`grpc.Dial("127.0.0.1:1", OPTIONS...)`,
		`grpc.DialContext(ctx, "127.0.0.1:1", OPTIONS...)`,
		`gen.RegisterSvcServiceHandlerFromEndpoint(ctx, nil, "127.0.0.1:1", OPTIONS)`,
	} {
		for _, options := range []string{"opts", "gatewayDialOptions(extra...)"} {
			t.Run(dial+options, func(t *testing.T) {
				dials := strings.Replace(fixtureDials,
					`_, _ = grpc.NewClient("127.0.0.1:1", opts...)`,
					strings.Replace(dial, "OPTIONS", options, 1), 1)
				if violations := judge(t, map[string]string{"grpc_gen.go": fixtureSeam, "rest_gen.go": dials}); len(violations) != 0 {
					t.Fatalf("refused direct or unescaped local options: %q", violations)
				}
			})
		}
	}
}
